import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.M7K9TQZf.js";const g=JSON.parse('{"title":"디자인 언어","description":"Plass의 표면은 맑은 시트 위에 놓인, 색이 들어간 유리 키입니다. 아래의 모든 규칙은 이 한 문장에서 나옵니다. 새 컴포넌트를 만들다 확신이 서지 않으면 이 문장으로, 그리고 이 문장이 모든 표면에 던지는 질문으로 돌아오세요.","frontmatter":{"title":"디자인 언어","order":1},"headers":[],"relativePath":"ko/design/design-language.md","filePath":"ko/design/design-language.md","lastUpdated":1788615590000}'),i={name:"ko/design/design-language.md"};function d(n,e,l,r,c,p){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="디자인-언어" tabindex="-1">디자인 언어 <a class="header-anchor" href="#디자인-언어" aria-label="Permalink to &quot;디자인 언어&quot;">​</a></h1><p>Plass의 표면은 <strong>맑은 시트 위에 놓인, 색이 들어간 유리 키</strong>입니다. 아래의 모든 규칙은 이 한 문장에서 나옵니다. 새 컴포넌트를 만들다 확신이 서지 않으면 이 문장으로, 그리고 이 문장이 모든 표면에 던지는 질문으로 돌아오세요.</p><blockquote><p><strong>이것은 눌리는 것인가, 무언가를 담는 것인가?</strong></p></blockquote><p>눌리는 것은 색이 들어간 유리입니다. 색 계열의 두 끝 사이를 훑는 그러데이션, 그 계열로 드리우는 그림자, 그리고 포인터를 따라 표면 위를 옮겨 다니는 빛. 무언가를 담는 것은 맑은 유리입니다. 반투명하고, 강하게 흐려져 있고, 흰 hairline을 두르고, 절대 물들지 않습니다. 세 번째 답은 없으며, 세 번째가 필요해 보이는 컴포넌트는 사실 두 개의 컴포넌트입니다.</p><p>이 문장이 가져온 것과 버린 것:</p><ul><li><strong>가져온 것</strong>: 빛의 방향, 컨트롤이 드리우는 그림자로 번지는 색, 그리고 포인터와 함께 도착하는 빛.</li><li><strong>버린 것</strong>: 모든 종류의 요철(bevel, specular highlight, 키 아래의 어두운 선, 부피감) 그리고 컨트롤을 움직여 표현하는 모든 상태.</li></ul><blockquote><p><strong>여기가 Plass가 플라스틱 라이브러리이기를 그만둔 지점입니다.</strong> 초안은 채워진 컨트롤을 성형된 키로 그렸습니다. 한쪽 모서리에서 밝아지고 반대쪽에서 어두워지는 세 지점 그러데이션에, 그 위 절반을 덮는 specular highlight를 얹어 마무리하는 식이었습니다. 하나하나는 앞뒤가 맞았지만 결과는 전부 래커칠처럼 읽혔습니다. 그 자리를 대신한 것이 아래이고, 결국 한 가지 생각입니다. <strong>음영을 지는 그러데이션이 아니라, 방향을 트는 그러데이션.</strong></p></blockquote><hr><h2 id="_1-두-가지-재질" tabindex="-1">1. 두 가지 재질 <a class="header-anchor" href="#_1-두-가지-재질" aria-label="Permalink to &quot;1. 두 가지 재질&quot;">​</a></h2><h3 id="색이-들어간-유리" tabindex="-1">색이 들어간 유리 <a class="header-anchor" href="#색이-들어간-유리" aria-label="Permalink to &quot;색이 들어간 유리&quot;">​</a></h3><p><code>solid</code> 표면은 세 겹이고, 세 겹뿐인 것이 의도입니다.</p><table tabindex="0"><thead><tr><th>겹</th><th>토큰</th><th>하는 일</th></tr></thead><tbody><tr><td>채움</td><td><code>--plass-{color}-fill</code></td><td>135°의 두 지점 그러데이션</td></tr><tr><td>tint</td><td><code>--plass-{color}-tint</code></td><td>컨트롤 자신의 색으로 드리우는 drop shadow</td></tr><tr><td>glow</td><td><code>.plass-glow</code></td><td>포인터를 따라 움직이는 빛</td></tr></tbody></table><p><strong>채움은 그러데이션이고, 그 그러데이션은 음영을 지는 대신 방향을 틉니다.</strong> 두 지점은 색 계열의 두 끝이며 <em>같은 밝기</em> 입니다. primary는 인디고에서 애저로, danger는 버밀리언에서 로즈로, success는 초록에서 틸로, info는 파랑에서 시안으로 갑니다. 밝아지는 것도 어두워지는 것도 없습니다.</p><p>highlight 레이어가 없는 이유가 바로 이것입니다. 한쪽 모서리로 어두워지는 그러데이션은 램프를 받고 있는 성형된 물체이고, 그런 물체는 환영을 완성하기 위해 specular highlight를 필요로 합니다. 채워진 컨트롤이 래커칠처럼 읽히게 만든 것이 정확히 그것이었습니다. 방향을 트는 그러데이션은 색이 들어간 유리판이고, 유리판에는 더 필요한 것이 없습니다.</p><p><strong>채워진 컨트롤에는 highlight도 bevel도 없습니다.</strong> 위쪽 가장자리의 흰 inset 선(<code>inset 0 1px 0 white</code>)은 색이 칠해진 표면을 성형품처럼 보이게 만드는 가장 빠른 방법이고, 그 아래의 <code>inset 0 -1px 0 black</code>이 두 번째입니다. hairline은 <code>glass</code>의 것입니다. 유리에는 빛이 걸릴 실제 절단면이 있기 때문입니다. <code>solid</code> 컨트롤에는 그림자 하나가 있고 가장자리는 없습니다.</p><p><strong>어디서나 135°.</strong> 채움과 elevation이 모두 왼쪽 위에서 오는 빛을 전제합니다. 이 중 하나가 다른 곳을 가리키면 물체가 두 개로 읽힙니다.</p><h3 id="유리" tabindex="-1">유리 <a class="header-anchor" href="#유리" aria-label="Permalink to &quot;유리&quot;">​</a></h3><p>콘텐츠를 담는 모든 것은 세 단계의 시트 하나입니다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>--plass-glass         rgb(255 255 255 / 0.62)   기본</span></span>\n<span class="line"><span>--plass-glass-hover   rgb(255 255 255 / 0.76)</span></span>\n<span class="line"><span>--plass-glass-press   rgb(255 255 255 / 0.88)</span></span></code></pre></div><p><strong>사다리는 밝기가 아니라 불투명도입니다.</strong> 표면은 관여될수록 회색이 되는 대신 더 많은 빛을 머금습니다.</p><p><strong>blur가 곧 재질입니다.</strong> <code>blur(22px) saturate(160%)</code>. 의도적으로 후한 번짐입니다. Plass는 시트 뒤를 읽게 하려는 것이 아니라 시트를 두꺼워 보이게 하려는 것입니다. 14px 아래로 내려가면 유리는 유리이기를 그만두고 알파가 걸린 흰 상자가 됩니다.</p><p><strong>유리는 물들지 않습니다.</strong> 시트는 다른 사람의 콘텐츠를 담고, 그 콘텐츠는 자기 색을 가지고 옵니다. 본문 글자, 링크, 버튼, 필드. 아래 시트를 물들이면 그 전부가 자신이 선택된 적 없는 배경 위에 놓입니다. 그래서 <strong>계열은 hairline과 focus ring, 캐럿에서 멈추고 유리는 맑게 남습니다.</strong></p><p>컨트롤은 반대 경우여서 계열을 채움 자체에 들입니다. PlButton의 표면은 <em>색이 칠해지는 대상 그 자체</em> 이기 때문입니다.</p><blockquote><p><strong>한 가지 결과.</strong> <code>glass</code> PlButton에서 <code>color</code>는 라벨과 hairline입니다. <code>glass</code> PlTextField에서 <code>color</code>는 hairline과 ring, 캐럿뿐입니다. invalid가 된 필드가 표면을 다시 칠하지 않고도 계열 전체를 <code>danger</code>로 넘길 수 있는 이유가 이것입니다.</p></blockquote><h3 id="하나뿐인-inset-그림자" tabindex="-1">하나뿐인 inset 그림자 <a class="header-anchor" href="#하나뿐인-inset-그림자" aria-label="Permalink to &quot;하나뿐인 inset 그림자&quot;">​</a></h3><p><code>--plass-well</code>은 이 짝을 증명하는 예외입니다. 라이브러리에서 유일하게 <strong>안쪽으로</strong> 향하는 그림자입니다. <code>solid</code> PlTextField가 그려지는 방식이며(가장 불투명한 유리에 빛이 안으로 떨어지는 형태) 캐럿과 텍스트 선택, placeholder 아래에 깔린 그러데이션은 읽히지 않기 때문입니다.</p><p>그래서 <code>solid</code>는 눌리는 것에서는 &quot;색이 들어간 판&quot;, 입력하는 것에서는 &quot;가장 깊은 맑은 유리&quot;를 뜻합니다. 같은 단어이고, 그 아래 규칙은 하나입니다. <code>solid</code>는 그 variant가 제 일을 하면서 가질 수 있는 가장 무거운 것입니다.</p><hr><h2 id="_2-색" tabindex="-1">2. 색 <a class="header-anchor" href="#_2-색" aria-label="Permalink to &quot;2. 색&quot;">​</a></h2><p>이 절은 <em>왜</em> 에 대한 것입니다. 토큰이 실제로 어떤 값이고 어떻게 덮어쓰는지는 <a href="./color">색</a>에 있습니다.</p><p>기준 색은 <code>#3558ef</code>이고 나머지는 그 팔레트에서 나옵니다.</p><table tabindex="0"><thead><tr><th>역할</th><th>어디서 왔는지</th></tr></thead><tbody><tr><td><code>primary</code></td><td>기준 색</td></tr><tr><td><code>secondary</code></td><td>기준 색의 hue를 유지한 slate</td></tr><tr><td><code>success</code></td><td>흰 글자를 얹을 만큼 어두운 초록</td></tr><tr><td><code>warning</code></td><td>보색 앰버, 유일하게 어두운 잉크를 쓰는 계열</td></tr><tr><td><code>danger</code></td><td>톤을 낮춘 버밀리언</td></tr><tr><td><code>info</code></td><td>유사색 azure</td></tr></tbody></table><h3 id="계열마다-손으로-고르는-값-셋" tabindex="-1">계열마다 손으로 고르는 값 셋 <a class="header-anchor" href="#계열마다-손으로-고르는-값-셋" aria-label="Permalink to &quot;계열마다 손으로 고르는 값 셋&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>--plass-{color}-solid       훑기의 한쪽 끝이자 계열의 정체성</span></span>\n<span class="line"><span>--plass-{color}-solid-to    반대쪽 끝</span></span>\n<span class="line"><span>--plass-{color}-on-solid    두 지점 위의 잉크</span></span>\n<span class="line"><span>--plass-{color}-accent      표면 위에서 읽히는 색 — 테마별</span></span></code></pre></div><p>나머지(<code>-fill</code>, <code>-tint</code>, <code>-soft</code>, <code>-line</code>, <code>-ring</code>)는 파생 블록에서 <code>color-mix()</code>로 계산됩니다. <strong>색 계열 추가는 두 번의 편집입니다</strong>, <code>PlassColor</code> union에 항목 하나, <code>styles.css</code>에 세 줄, 그리고 각 테마의 <code>accent</code>.</p><h3 id="테마가-바뀌어도-같은-키-색" tabindex="-1">테마가 바뀌어도 같은 키 색 <a class="header-anchor" href="#테마가-바뀌어도-같은-키-색" aria-label="Permalink to &quot;테마가 바뀌어도 같은 키 색&quot;">​</a></h3><p><strong>파란 유리판은 어두운 방에서도 같은 파란 유리판입니다.</strong> 다크 모드에서 바뀌는 것은 그것이 놓인 바닥입니다. 맑은 유리는 흰빛을 잃고 스모크 판이 되고, 그림자는 검게 깊어지며, 그 그림자로 번지는 tint는 강해집니다. 거의 검은 페이지 위에서는 색이 물든 그림자가 앉을 자리가 거의 없기 때문입니다.</p><p>테마별로 바뀌는 유일한 계열 값은 <code>accent</code>입니다. 바라보는 색이 아니라 <strong>읽어야 하는</strong> 색이기 때문입니다.</p><h3 id="두-끝은-대비-하한에-최대한-붙여-둡니다" tabindex="-1">두 끝은 대비 하한에 최대한 붙여 둡니다 <a class="header-anchor" href="#두-끝은-대비-하한에-최대한-붙여-둡니다" aria-label="Permalink to &quot;두 끝은 대비 하한에 최대한 붙여 둡니다&quot;">​</a></h3><p>모든 지점이 자기 <code>on-solid</code>에 대해 4.5:1을 넘기고, 그 전부가 정확히 4.5에서 0.15 이내에 있습니다. 반대 방향의 소심함이 아닙니다. 하한보다 필요 이상으로 높이 띄운 계열은 <strong>필요 이상으로 어두운</strong> 계열이고, 버튼이 전부 한 톤씩 깊게 깔린 팔레트야말로 팔레트가 조용히 어긋나는 가장 흔한 방식입니다.</p><p>그래서 제약은 양쪽입니다. 하한이 계열이 얼마나 밝을 수 있는지를 정하고, 그보다 어둡게 만드는 것은 무엇도 허용되지 않습니다.</p><h3 id="warning은-어두운-글자를-씁니다" tabindex="-1"><code>warning</code>은 어두운 글자를 씁니다 <a class="header-anchor" href="#warning은-어두운-글자를-씁니다" aria-label="Permalink to &quot;`warning`은 어두운 글자를 씁니다&quot;">​</a></h3><p>앰버라 부를 만한 어떤 밝기에서도 흰 글자는 4.5:1에 닿지 않습니다. <code>--plass-warning-on-solid</code>는 이 세트에서 유일한 짙은 갈색입니다. 잉크를 바꾸는 것이 옳은 답이고, 흰 라벨을 지키려고 계열을 일그러뜨리는 것은 아닙니다.</p><hr><h2 id="_3-크기와-density" tabindex="-1">3. 크기와 density <a class="header-anchor" href="#_3-크기와-density" aria-label="Permalink to &quot;3. 크기와 density&quot;">​</a></h2><h3 id="size-높이와-타입-스케일" tabindex="-1"><code>size</code>: 높이와 타입 스케일 <a class="header-anchor" href="#size-높이와-타입-스케일" aria-label="Permalink to &quot;`size`: 높이와 타입 스케일&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>xs</th><th>sm</th><th>md</th><th>lg</th><th>xl</th></tr></thead><tbody><tr><td>높이</td><td>24px</td><td>32px</td><td><strong>40px</strong></td><td>48px</td><td>56px</td></tr><tr><td>글자</td><td>11px</td><td>13px</td><td><strong>14px</strong></td><td>16px</td><td>18px</td></tr><tr><td>radius</td><td>8px</td><td>10px</td><td><strong>12px</strong></td><td>14px</td><td>16px</td></tr></tbody></table><p>사다리는 한 단계에 8px씩 일정하고, 조밀한 데스크톱 툴킷보다 높은 데서 시작합니다. 재질이 자리를 요구하기 때문입니다. 방향을 틀어야 하는 그러데이션과 hairline을 32px 안에 넣는 것은 열한 픽셀의 채움을 두고 두 효과가 싸우는 일입니다. <code>xs</code>는 테이블 행을 위해 존재하며, 훑는 거리가 짧아 두 끝이 거의 맞닿는 유일한 단계입니다.</p><p><code>lg</code> 48px과 <code>xl</code> 56px은 모두 모바일 터치 타깃 44px을 넘깁니다.</p><h3 id="radius는-fillet" tabindex="-1">radius는 fillet <a class="header-anchor" href="#radius는-fillet" aria-label="Permalink to &quot;radius는 fillet&quot;">​</a></h3><p>높이보다 훨씬 느리게 자랍니다. <code>xs</code>에서 33%, <code>md</code>에서 29%, <code>xl</code>에서 29%. 거의 일정한 그 radius가 크기가 다른 두 컨트롤을 같은 틀에서 뽑은 두 조각으로 읽히게 합니다. 높이의 비율로 묶은 radius는 대신 작은 알약과 큰 사각형을 만들어 냅니다.</p><h3 id="density-여백-오직-여백" tabindex="-1"><code>density</code>: 여백, 오직 여백 <a class="header-anchor" href="#density-여백-오직-여백" aria-label="Permalink to &quot;`density`: 여백, 오직 여백&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>default   10 / 12 / 16 / 24 / 28px</span></span>\n<span class="line"><span>compact    6 /  8 / 10 / 14 / 16px</span></span></code></pre></div><p><strong>density는 높이도 타입 스케일도 건드리지 않습니다.</strong> 같은 <code>size</code>의 두 컨트롤은 density와 무관하게 높이가 같아서, density가 섞인 줄도 기준선을 유지합니다. 두 트랙은 대략 2:1이라 차이가 한눈에 읽힙니다.</p><hr><h2 id="_4-elevation" tabindex="-1">4. Elevation <a class="header-anchor" href="#_4-elevation" aria-label="Permalink to &quot;4. Elevation&quot;">​</a></h2><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> PlassElevation</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p><strong>PlButton의 기본값은 <code>1</code>, PlTextField는 <code>0</code>입니다.</strong> 키는 시트 <em>위에</em> 놓이고, 필드는 시트 <em>안으로</em> 파입니다. 호버는 한 단계를 올리고 누르면 한 단계를 내리므로, 기본 버튼은 유리에 딱 닿는 데까지 내려갔다가 원래 자리로 돌아옵니다.</p><p>사다리는 <strong>offset보다 blur로 훨씬 많이 올라갑니다.</strong> 들렸을 때 페이지에서 20px씩 내려가는 표면은 이미 시트를 떠난 것이고, 이 라이브러리의 모든 것은 여전히 시트 위에 앉아 있습니다.</p><h3 id="그림자는-물들고-plass가-절제와-갈라서는-지점이-여기입니다" tabindex="-1">그림자는 물들고, Plass가 절제와 갈라서는 지점이 여기입니다 <a class="header-anchor" href="#그림자는-물들고-plass가-절제와-갈라서는-지점이-여기입니다" aria-label="Permalink to &quot;그림자는 물들고, Plass가 절제와 갈라서는 지점이 여기입니다&quot;">​</a></h3><p><code>--plass-{color}-tint</code>는 컨트롤이 자기 색으로 드리우는 drop shadow이고, 이 디자인 언어에서 단연 가장 시끄러운 요소입니다. 파란 버튼과 파랑으로 <em>만들어진</em> 버튼의 차이가 이것입니다.</p><p>이것은 의도적으로 <strong>elevation 사다리의 일부가 아니며</strong> 함께 커지지 않습니다. elevation은 표면이 페이지에서 얼마나 떠 있는지를, tint는 표면이 무엇으로 만들어졌는지를 말합니다. 한 단계 높은 <code>danger</code> 버튼이 더 붉은 유리판은 아닙니다.</p><p>tint를 가지는 것은 <code>solid</code>뿐입니다. 맑은 유리 시트는 중립적인 그림자를 드리웁니다. 자기 색이 없기 때문입니다.</p><hr><h2 id="_5-모션" tabindex="-1">5. 모션 <a class="header-anchor" href="#_5-모션" aria-label="Permalink to &quot;5. 모션&quot;">​</a></h2><h3 id="컨트롤은-움직이지-않습니다" tabindex="-1">컨트롤은 움직이지 않습니다 <a class="header-anchor" href="#컨트롤은-움직이지-않습니다" aria-label="Permalink to &quot;컨트롤은 움직이지 않습니다&quot;">​</a></h3><p><strong>컨트롤에 <code>transform</code>을 쓰지 마세요.</strong> 컨트롤을 확대하면 라벨이 리샘플링되고, 커서 아래에서 아른거리는 글자는 나머지 전부가 들이고 있는 절제를 무너뜨립니다. 상태 변화는 오직 <strong>빛과 깊이</strong>로 표현합니다.</p><p>눌리는 대신 콘텐츠를 <em>담는</em> 표면(Card나 행)은 떠올라도 되고, 떠올라야 합니다. 이 규칙은 손가락 아래에 있는 것에 대한 규칙입니다.</p><p>위치에 애니메이션을 주는 곳은 <a href="./../components/inputs/slider"><code>PlSlider</code></a>의 thumb 하나뿐이고, 그것도 예외가 아닙니다. 제자리에서 밀려나는 것은 없고, 움직이는 것이 곧 값이기 때문입니다. 끌지 않은 이동(화살표 키, rail을 누른 것) 에는 이동하고, 손가락 아래에서는 전혀 이동하지 않습니다. 포인터를 향해 서서히 따라가 봐야 지연으로만 읽힙니다.</p><h3 id="표식을-그리는-방법" tabindex="-1">표식을 그리는 방법 <a class="header-anchor" href="#표식을-그리는-방법" aria-label="Permalink to &quot;표식을 그리는 방법&quot;">​</a></h3><p>위 규칙은 빈틈을 하나 남깁니다. 체크 표시와 라디오 점은 없다가 생기는 것인데, 둘 다 확대해서 등장시킬 수 없습니다. 그래서 갖다 놓지 않고 <strong>그립니다</strong>.</p><ul><li><strong>체크 표시는 자기 경로를 따라 그려집니다.</strong> 획을 자기 길이만큼의 점선으로 만들고 딱 그만큼 밀어내면, 표식이 얼마나 존재하는지가 0과 1 사이의 숫자 하나가 됩니다. CSS에서는 <code>stroke-dashoffset</code>이고 Flutter에서는 경로를 재서 잘라낸 것입니다. 최종 위치가 아닌 곳에는 아무것도 나타나지 않습니다.</li><li><strong>라디오 점은 고리 한가운데에서 자랍니다.</strong> 고리는 고정 크기 자식을 가운데 두므로 너비와 높이가 같은 점을 중심으로 배치됩니다. 상자가 커질 뿐 <code>transform</code>은 쓰지 않고, 고리 바깥의 무엇도 이 때문에 움직이지 않습니다.</li></ul><p>표식은 <strong>없는 동안에도 문서에 남아</strong> 크기 0으로 있습니다. 값이 지워지는 순간 버려지는 표식은 되돌아 나갈 수 없고, 한쪽 방향은 애니메이션이고 반대쪽은 잘라내는 컨트롤은 같은 클릭으로 두 가지를 말하는 컨트롤입니다.</p><h3 id="눌림은-칠이-아니라-빛" tabindex="-1">눌림은 칠이 아니라 빛 <a class="header-anchor" href="#눌림은-칠이-아니라-빛" aria-label="Permalink to &quot;눌림은 칠이 아니라 빛&quot;">​</a></h3><p>채움은 그러데이션이고 그러데이션은 transition되지 않습니다. 그래서 호버와 눌림은 <code>filter: brightness()</code>입니다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hover   brightness(1.05)  + elevation 한 단계 위, tint가 퍼짐</span></span>\n<span class="line"><span>active  brightness(0.95)  + 한 단계 아래, 그 밑에서 tint가 오므라듦</span></span></code></pre></div><p>세 가지가 함께 움직이고, 셋 다 같은 말을 합니다. 컨트롤이 내려갔고 그 아래에 자기 그림자가 들어갈 자리가 줄었다.</p><h3 id="하나의-duration-양방향-동일" tabindex="-1">하나의 duration, 양방향 동일 <a class="header-anchor" href="#하나의-duration-양방향-동일" aria-label="Permalink to &quot;하나의 duration, 양방향 동일&quot;">​</a></h3><p><code>--plass-duration</code>은 150ms이고 <code>--plass-ease</code>는 하나의 곡선이며, 양방향에 똑같이 적용됩니다. 내려가는 컨트롤과 올라오는 컨트롤은 같은 스프링입니다. 비대칭한 눌림은 다른 재질의 것입니다.</p><h3 id="두-번째-duration" tabindex="-1">두 번째 duration <a class="header-anchor" href="#두-번째-duration" aria-label="Permalink to &quot;두 번째 duration&quot;">​</a></h3><p><code>--plass-duration-slow</code>는 260ms이고, 표면이 둘 중 무엇을 쓸지는 딱 하나가 정합니다. <strong>페이지를 가져가는가, 컨트롤에 매달리는가.</strong></p><ul><li><strong>페이지를 가져감</strong>: modal, drawer, overlay, command palette. 시트와 그 아래 scrim이 둘 다 느린 duration으로 사라지고 나타나므로 한 덩어리로 도착합니다. 창 전체에 걸친 150ms는 페이드가 아니라 블러가 살짝 묻은 컷이고, 이렇게 통째로 바뀌는 화면이 그 속도로 바뀌면 읽는 사람은 무엇이 움직였는지 찾게 됩니다.</li><li><strong>컨트롤에 매달림</strong>: menu, popover, tooltip, select와 combobox의 목록, date picker의 시트. 이쪽은 150ms 그대로입니다. 자기가 나온 컨트롤만 한 크기이고, 읽는 사람은 대개 그 안의 무언가로 가는 중이기 때문입니다.</li></ul><p>높이가 움직이는 시간도 같은 260ms입니다. accordion, collapsible, pill이 그렇고, 이유도 같습니다. 움직이는 것이 그 아래의 페이지이기 때문입니다.</p><h3 id="빛은-포인터와-함께-도착합니다" tabindex="-1">빛은 포인터와 함께 도착합니다 <a class="header-anchor" href="#빛은-포인터와-함께-도착합니다" aria-label="Permalink to &quot;빛은 포인터와 함께 도착합니다&quot;">​</a></h3><p><code>.plass-glow</code>는 상호작용 가능한 모든 컨트롤 위의 두 겹입니다.</p><ul><li><strong><code>::before</code>는 bloom</strong>: 포인터를 중심으로 한 부드러운 원형 빛. 포인터가 들어오면 240ms에 걸쳐 나타나고, 표면 위를 따라 움직입니다.</li><li><strong><code>::after</code>는 눌림</strong>: 같은 모양을 한 단계 밝게, 들어올 때 <code>0ms</code>, 나갈 때 약 700ms. 클릭한 프레임에 빛이 앉고, 손가락이 떨어진 뒤에도 한 박자 동안 눈에 띄게 빠져나갑니다.</li></ul><p>둘 다 <code>--p-mx</code> / <code>--p-my</code>를 읽고, 컴포넌트가 <code>pointermove</code>에서 그 값을 <strong>요소의 inline style에 직접</strong> 씁니다.</p><p><strong>이걸 React state에 담지 마세요.</strong> 이벤트는 포인터 속도로 발생하므로 <code>setState</code>는 마우스가 움직일 때마다 트리를 다시 렌더링합니다. 좌표는 <code>getBoundingClientRect()</code>가 아니라 <code>offsetX</code>/<code>offsetY</code>에서 오므로 reflow를 강제하지 않습니다. 아이콘에는 <code>pointer-events: none</code>이 걸려 있어 offset은 언제나 컨트롤 기준입니다.</p><p>이것이 정적인 specular highlight를 대신했고, 그 이유는 기억해 둘 값어치가 있습니다. <strong>항상 켜져 있는 highlight는 화면 밖 어딘가의 램프에 대한 주장이고, 그래서 래커칠처럼 읽힙니다. 포인터와 함께 도착하는 빛은 포인터에 대한 주장이고, 그건 사실입니다.</strong></p><p><code>::after</code> 겹은 hover가 아예 없는 터치 화면에서 이 효과를 지탱하는 쪽이기도 합니다. 손가락이 닿아 있는 동안 <code>:active</code>가 유지되고 <code>pointermove</code>가 좌표를 계속 쓰므로, 컨트롤 위를 끄는 손가락을 빛이 따라갑니다.</p><p>두 색 slot은 variant를 따라 바뀝니다. 흰빛은 거의 흰 시트 위에서 보이지 않기 때문입니다. 채워진 컨트롤은 <code>--plass-glow-on-fill</code>(흰색 18%)을, <code>glass</code>나 <code>ghost</code>는 자기 계열의 soft tint를 씁니다.</p><hr><h2 id="_6-상태" tabindex="-1">6. 상태 <a class="header-anchor" href="#_6-상태" aria-label="Permalink to &quot;6. 상태&quot;">​</a></h2><p>세 상태는 각자 자기 축에서 말해야 하고, 각각 기본 상태와 한눈에 구별되어야 합니다.</p><table tabindex="0"><thead><tr><th>상태</th><th>어떻게 표현하는지</th><th>왜</th></tr></thead><tbody><tr><td><code>disabled</code></td><td><code>opacity: 0.5</code>와 <code>saturate(0.35)</code>, 빛도 그림자도 없음</td><td>반투명 시트로 만든 페이지에서, 페이지가 <em>통과해 보이는</em> 표면은 물체이기를 그만둔 것입니다</td></tr><tr><td><code>loading</code></td><td>그대로, <code>startIcon</code> 자리에 스피너</td><td>사용 불가가 아니라 진행 중입니다</td></tr><tr><td><code>readOnly</code></td><td>색은 유지, 평평해지고 <code>saturate(0.55)</code></td><td>컨트롤 모양을 한 라벨입니다</td></tr></tbody></table><p>네이티브 <code>disabled</code> 속성을 쓰는 것은 <code>disabled</code>뿐입니다. <code>loading</code>과 <code>readOnly</code>는 <code>aria-disabled</code>로 표시되고 focus를 유지하며, 핸들러에서 활성화를 막습니다.</p><blockquote><p><strong>여기서 opacity는 실제로 일을 합니다.</strong> <code>opacity: 0.5</code>에 대한 흔한 비판은 상태와 무관하게 &quot;흐릿함&quot;으로 읽힌다는 것이고, 불투명한 페이지에서는 실제로 그렇습니다. 이 페이지에서는 페이지가 컨트롤을 <em>통과해</em> 오는 것으로 읽히는데, 그건 구체적인 말이고 그 말을 하는 상태는 하나뿐입니다. <code>disabled</code>만 쓰는 축이고 다른 상태는 건드리지 않습니다.</p></blockquote><hr><h2 id="_7-구현-규칙" tabindex="-1">7. 구현 규칙 <a class="header-anchor" href="#_7-구현-규칙" aria-label="Permalink to &quot;7. 구현 규칙&quot;">​</a></h2><h3 id="상태-분기는-css가-아니라-js에서" tabindex="-1">상태 분기는 CSS가 아니라 JS에서 <a class="header-anchor" href="#상태-분기는-css가-아니라-js에서" aria-label="Permalink to &quot;상태 분기는 CSS가 아니라 JS에서&quot;">​</a></h3><p>같은 specificity가 붙은 두 Tailwind variant는 <strong>생성된 스타일시트에서의 순서</strong>로 결정됩니다. 컴포넌트가 기대도 되는 성질이 아닙니다.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 이렇게</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">disabled </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> disabledClasses[variant] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> readOnly </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> readOnlyClasses[variant] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> restClasses[variant];</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 이렇게 말고 — data-disabled:와 data-readonly:의 우선순위는 정의되어 있지 않습니다</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;data-disabled:opacity-50 data-readonly:saturate-50&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><h3 id="색-slot은-inline-style로" tabindex="-1">색 slot은 inline style로 <a class="header-anchor" href="#색-slot은-inline-style로" aria-label="Permalink to &quot;색 slot은 inline style로&quot;">​</a></h3><p>Tailwind는 <strong>소스에 문자 그대로 나타난 클래스 이름</strong>만 봅니다. <code>[--p-fill:var(--plass-primary-fill)]</code>을 계열마다 하드코딩하면 색을 하나 추가할 때마다 클래스가 수십 개씩 늘어납니다. 대신 <code>--p-*</code> slot을 inline style로 생성하세요.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;--p-fill&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`var(--plass-${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">color</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}-fill)`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Tailwind 바깥으로 나가는 이유는 이 종류뿐입니다. <strong>Tailwind가 표현할 수 없을 때만 바깥으로 나가세요.</strong></p><h3 id="파생-토큰은-테마-root마다-반복합니다" tabindex="-1">파생 토큰은 테마 root마다 반복합니다 <a class="header-anchor" href="#파생-토큰은-테마-root마다-반복합니다" aria-label="Permalink to &quot;파생 토큰은 테마 root마다 반복합니다&quot;">​</a></h3><p>custom property는 자기 <code>var()</code>를 <strong>그것이 선언된 요소에서</strong> 풉니다. <code>--plass-primary-tint</code>는 테마별 값인 <code>--plass-tint-strength</code>를 읽으므로, <code>:root</code>에만 선언하면 <code>.dark</code> 하위 트리 안에서도 라이트 테마 값으로 굳습니다. 파생 블록의 selector가 <code>:root, .dark, .light, [data-theme=&#39;dark&#39;], [data-theme=&#39;light&#39;]</code>인 이유입니다.</p><h3 id="포털의-쌓임-순서" tabindex="-1">포털의 쌓임 순서 <a class="header-anchor" href="#포털의-쌓임-순서" aria-label="Permalink to &quot;포털의 쌓임 순서&quot;">​</a></h3><p>흐름을 벗어나는 표면(modal, drawer, menu, select의 목록, popover, tooltip, toast)은 전부 <code>var(--plass-z-portal)</code> 높이에 그려집니다. 기본값은 <code>50</code>이고, 페이지가 한 줄로 바꿀 수 있습니다. 무엇이 무엇 위에 뜨는지는 앱이 dialog를 꺼내기 전에 이미 정해 둔 문제입니다. 헤더가 있거나, 쿠키 배너가 있거나, 비디오 플레이어가 있고, 여기서 고른 숫자는 남이 세운 사다리에 대한 추측일 뿐입니다.</p><p>전부 <strong>같은</strong> 토큰을 읽는 것도 의도입니다. 서로 다른 값을 주는 순간, modal 안에서 연 select가 modal 뒤로 들어갑니다.</p><p>이 토큰은 맨 <code>:root</code>에만 선언하고 어느 테마 블록에도 반복하지 않습니다. 바로 위 규칙의 예외이고, 그 규칙이 있는 이유와 같은 이유입니다. 테마 블록은 자기가 가진 것을 다시 선언하므로, 그 안에 들어간 토큰은 테마 클래스를 단 중첩 요소마다 소비자가 정한 값을 되돌려 버립니다.</p><h3 id="읽히지-않게-되면-css로-옮깁니다" tabindex="-1">읽히지 않게 되면 CSS로 옮깁니다 <a class="header-anchor" href="#읽히지-않게-되면-css로-옮깁니다" aria-label="Permalink to &quot;읽히지 않게 되면 CSS로 옮깁니다&quot;">​</a></h3><p><code>.plass-glow</code>가 Tailwind utility 묶음이 아니라 <code>styles.css</code>의 실제 클래스인 이유는 <code>[&amp;::before]:[background:radial-gradient(…)]</code>가 기술적으로는 표현 가능하지만 유지할 수 없기 때문입니다. pseudo-element에 그러데이션을 얹는 스타일은 CSS에 속합니다.</p><h3 id="outline-none은-절대-쓰지-않습니다" tabindex="-1"><code>outline-none</code>은 절대 쓰지 않습니다 <a class="header-anchor" href="#outline-none은-절대-쓰지-않습니다" aria-label="Permalink to &quot;`outline-none`은 절대 쓰지 않습니다&quot;">​</a></h3><p>Tailwind v4의 <code>outline-*</code> utility는 스타일을 <code>--tw-outline-style</code>을 통해 지정합니다. 요소 어딘가의 <code>outline-none</code>이 그 변수를 <code>none</code>으로 만들면 <strong>focus ring이 통째로 사라집니다.</strong> shorthand를 쓰세요.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>focus-visible:[outline:2px_solid_var(--p-ring)] focus-visible:[outline-offset:0px]</span></span></code></pre></div><h3 id="ring이-놓이는-자리" tabindex="-1">ring이 놓이는 자리 <a class="header-anchor" href="#ring이-놓이는-자리" aria-label="Permalink to &quot;ring이 놓이는 자리&quot;">​</a></h3><p>offset은 <code>0</code>이고, 라이브러리의 모든 컨트롤에서 <code>0</code>입니다. 자기 테두리가 붙은 컨트롤(field, select, tick, switch)에서 ring을 2px 띄우면 하나의 사물 주위에 사각형이 세 겹으로 읽히고, 사물이 자기 ring에서 떨어져 나온 것처럼 보입니다. 붙이면 outline이 테두리 바깥면에 그대로 닿고, 테두리가 두꺼워지면서 그 색 계열을 입은 것으로 읽힙니다.</p><p>테두리가 없는 컨트롤에서도 잃는 것은 없습니다. outline은 언제나 border box <strong>바깥</strong>에 그려지므로, 채워진 키에서는 칠 위에 겹친 띠가 아니라 페이지를 배경으로 한 테두리가 됩니다.</p><p>예외는 다른 것이 잘라내는 컨트롤 하나뿐입니다. 레일 위의 tab, 홈 안의 segment, 둥근 시트 안의 행, 금이 그어진 판 안의 accordion 헤더. 이들은 <code>focus-visible:[outline-offset:-2px]</code>을 씁니다. 바깥에 그린 ring은 위나 아래가 잘려 나가기 때문입니다.</p><h3 id="ring은-outline" tabindex="-1">ring은 <code>outline</code> <a class="header-anchor" href="#ring은-outline" aria-label="Permalink to &quot;ring은 `outline`&quot;">​</a></h3><p>Tailwind의 <code>ring-*</code>은 <code>box-shadow</code>이고, Plass의 모든 표면은 이미 <code>box-shadow</code>를 elevation과 tint, 그리고 유리의 hairline에 쓰고 있습니다. ring을 쓰려면 세 variant 각각의 chain에 끼워 넣어야 하고, 처음으로 그걸 빠뜨린 variant는 조용히 focus ring을 잃게 됩니다.</p>',123)])])}const u=a(i,[["render",d]]);export{g as __pageData,u as default};
